pub fn verify(proof: &VadcopFinalProof, vk: &[u64]) -> bool {
    stark_verify::<Blake3_8, Blake3_8, Blake3_8, Blake3_8>(&proof.proof_with_publics(), vk, &verifier_info(), q_verify, query_verify)
}

pub fn verify_u64(proof: &[u64], vk: &[u64]) -> bool {
    stark_verify::<Blake3_8, Blake3_8, Blake3_8, Blake3_8>(proof, vk, &verifier_info(), q_verify, query_verify)
}

pub fn expected_proof_bytes() -> usize {
    crate::expected_proof_size_bytes(&verifier_info())
}
